document.querySelector("[data-product-add]")?.addEventListener("click",i=>{const n=i.currentTarget,r=n.dataset.name,s=n.dataset.price;let t=[];try{const a=JSON.parse(localStorage.getItem("gd-cart")||"[]");Array.isArray(a)&&(t=a.filter(c=>c&&typeof c.name=="string"))}catch{}const e=t.find(a=>a.name===r);e?e.quantity=Math.min(999,(Number(e.quantity)||0)+1):t.push({name:r,price:s,quantity:1});try{localStorage.setItem("gd-cart",JSON.stringify(t))}catch{}window.location.assign("/catalog")});
